class Solution {
public:
    long long smallestNumber(long long num) {
        if (num == 0) return 0;
        if (num > 0) {
            string s = to_string(num);
            sort(s.begin(), s.end());
            int idx = 0;
            while (s[idx] == '0') idx++;
            swap(s[0], s[idx]);
            return stoll(s);
        } else {
            string s = to_string(-num);
            sort(s.rbegin(), s.rend());
            return -stoll(s);
        }
    }
};

class Solution {
    public long smallestNumber(long num) {
        if (num == 0) return 0;
        if (num > 0) {
            char[] ch = String.valueOf(num).toCharArray();
            Arrays.sort(ch);
            int idx = 0;
            while (ch[idx] == '0') idx++;
            char tmp = ch[0]; ch[0] = ch[idx]; ch[idx] = tmp;
            return Long.parseLong(new String(ch));
        } else {
            char[] ch = String.valueOf(-num).toCharArray();
            Arrays.sort(ch);
            StringBuilder sb = new StringBuilder(new String(ch)).reverse();
            return -Long.parseLong(sb.toString());
        }
    }
}

var smallestNumber = function(num) {
    if (num === 0) return 0;
    if (num > 0) {
        const digits = String(num).split('').sort();
        let idx = 0;
        while (digits[idx] === '0') idx++;
        [digits[0], digits[idx]] = [digits[idx], digits[0]];
        return Number(digits.join(''));
    } else {
        const digits = String(-num).split('').sort((a, b) => b.localeCompare(a));
        return -Number(digits.join(''));
    }
};
